package events

// subKey identifies the set of subscriptions belonging to one device's view
// of one document: change commits wake every device set under the document,
// a permission revoke closes only the one (document, device) set.
type subKey struct {
	document string
	device   string
}

// subscription is one in-memory, push-only observer of the change log.
//
// It belongs to a (document, device) pair — the device is the one owning the
// session that opened the connection. It receives one coalesceable signal per
// change-producing commit (PostChanges, ReplayChanges, MergeChange and
// RestoreSnapshot all signal through the same hook long polling uses). The
// permission service closes the separate one-shot revoked channel when it
// revokes the keyed pair; closing is sticky, so a later grant never reopens
// it.
//
// A subscription leaves no durable trace: nothing is written, a disconnect
// simply unregisters, and a stop broadcasts one final wakeup. Pushing never
// allocates a cursor or inserts a change row.
type subscription struct {
	// wakes receives one value on every change commit for the keyed document.
	// It is buffered (and signals coalesce) so a commit is never dropped or
	// blocked while the consumer is reading the log.
	wakes chan struct{}
	// revoked is closed once, the first time permission for the keyed pair is
	// revoked while this subscription is live. Closing is sticky.
	revoked       chan struct{}
	revokedClosed bool
}

// AddSubscription registers an in-memory subscription for documentID as seen
// by deviceID. It returns:
//
//   - wakes: signaled (coalesceably) after every change commit on documentID;
//   - revoked: closed once if/when permission for (documentID, deviceID) is
//     revoked while the subscription is live;
//   - unregister: idempotent removal; a client disconnect, a permission close
//     and a service stop may all race to call it.
//
// If the service is already stopping the wake channel is signaled immediately
// and unregister is a no-op, so a late subscriber parks on nothing.
func (s *Service) AddSubscription(documentID, deviceID string) (wakes <-chan struct{}, revoked <-chan struct{}, unregister func()) {
	ch := make(chan struct{}, 1)
	sub := &subscription{wakes: ch, revoked: make(chan struct{})}
	key := subKey{document: documentID, device: deviceID}

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		close(ch)
		return ch, sub.revoked, func() {}
	}
	s.subWG.Add(1)
	s.nextSub++
	id := s.nextSub
	set := s.subs[key]
	if set == nil {
		set = make(map[uint64]*subscription)
		s.subs[key] = set
	}
	set[id] = sub
	remove := func() {
		s.mu.Lock()
		if set, ok := s.subs[key]; ok {
			if _, ok := set[id]; ok {
				delete(set, id)
				if len(set) == 0 {
					delete(s.subs, key)
				}
				s.mu.Unlock()
				s.subWG.Done()
				return
			}
		}
		s.mu.Unlock()
	}
	return ch, sub.revoked, remove
}

// signalSubscribers wakes every subscription open on documentID. It is called
// only after a change-bearing transaction has committed, so when a woken
// subscription re-reads the log the new rows are visible.
func (s *Service) signalSubscribers(documentID string) {
	s.mu.Lock()
	var targets []chan struct{}
	for key, set := range s.subs {
		if key.document != documentID {
			continue
		}
		for _, sub := range set {
			targets = append(targets, sub.wakes)
		}
	}
	s.mu.Unlock()

	for _, ch := range targets {
		select {
		case ch <- struct{}{}:
		default:
			// A signal the consumer has not drained yet is already pending; the
			// pending wake covers this commit too because the consumer re-reads
			// from its last observed cursor.
		}
	}
}

// SignalRevoked closes the one-shot revoked channel of every subscription open
// on (documentID, deviceID), so the connection layer ends those subscriptions
// with the permission-closed code even if a grant races in afterward. Other
// devices' and other documents' subscriptions are untouched. It is the
// permission service's revoke hook for the change event service.
func (s *Service) SignalRevoked(documentID, deviceID string) {
	s.mu.Lock()
	set := s.subs[subKey{document: documentID, device: deviceID}]
	targets := make([]*subscription, 0, len(set))
	for _, sub := range set {
		if !sub.revokedClosed {
			sub.revokedClosed = true
			targets = append(targets, sub)
		}
	}
	s.mu.Unlock()

	for _, sub := range targets {
		close(sub.revoked)
	}
}

// SignalDeviceDeregistered ends every live subscription belonging to
// deviceID across every document, after the device's deregistration
// transaction committed: the session backing such a connection is already
// hard-deleted, so the connection closes immediately with the same
// permission-closed code a revoke uses — stickily, nothing can reopen it.
// Other devices' subscriptions are untouched.
func (s *Service) SignalDeviceDeregistered(deviceID string) {
	s.mu.Lock()
	var targets []*subscription
	for key, set := range s.subs {
		if key.device != deviceID {
			continue
		}
		for _, sub := range set {
			if !sub.revokedClosed {
				sub.revokedClosed = true
				targets = append(targets, sub)
			}
		}
	}
	s.mu.Unlock()

	for _, sub := range targets {
		close(sub.revoked)
	}
}

// Closing reports whether the service has begun stopping. A woken subscription
// uses it to distinguish a termination signal from a commit.
func (s *Service) Closing() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.closed
}

// interruptWaits wakes every parked long poll without closing the database, so
// an orderly shutdown drains waiting connections immediately (they answer 503)
// instead of holding shutdown hostage until their wait deadline. Committed
// state is untouched. Live subscriptions get one last wakeup as well; the
// connection layer re-checks the closed flag and finishes with a going-away
// close.
func (s *Service) InterruptWaits() {
	s.mu.Lock()
	s.closed = true
	waits := s.waits
	s.waits = map[string]map[uint64]chan struct{}{}
	// Snapshot the live subscription channels without reaping the registry:
	// unregister remains valid while handlers drain, so the WaitGroup in
	// shutdown balances. New AddSubscription calls fail fast on closed.
	var subChans []chan struct{}
	for _, set := range s.subs {
		for _, sub := range set {
			subChans = append(subChans, sub.wakes)
		}
	}
	s.mu.Unlock()
	for _, set := range waits {
		for _, ch := range set {
			close(ch)
		}
	}
	for _, ch := range subChans {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
}

// waitSubscriptions blocks until every subscription handler has unregistered.
func (s *Service) WaitDrained() {
	s.subWG.Wait()
}

// Package push holds the process-wide, in-memory registry of the live push
// connections — change subscriptions and CRDT state subscriptions alike.
//
// The registry is the management plane behind the device-scoped subscription
// list and cancel endpoints. It owns no durable state: a live entry exists
// exactly while its WebSocket connection does, so a client disconnect, an
// active cancel and a process restart all make the subscription vanish from
// every list immediately. Registration never writes a change, never advances
// a cursor and never writes a CRDT operation.
package push

import (
	"sort"
	"strconv"
	"sync"
	"time"
)

// Kind names one of the two push channels a subscription can ride.
type Kind string

const (
	// KindChanges is the change-log subscription: it replays committed
	// changes past a handshake cursor and fans out later commits.
	KindChanges Kind = "changes"
	// KindState is the CRDT state subscription: it pushes the current merged
	// state and every later merge that actually changes it; it carries no
	// cursor.
	KindState Kind = "state"
)

// Info is the immutable description of one live push connection. Cursor is the
// starting cursor requested at the handshake (0 for a state subscription,
// which has no cursor); EstablishedAt is the connection's establishment time
// as a Unix millisecond timestamp.
type Info struct {
	ID            string
	DeviceID      string
	DocumentID    string
	Kind          Kind
	Cursor        int64
	EstablishedAt int64
	seq           uint64
}

// Subscription is one live registry entry. Its one-shot Canceled channel is
// closed exactly when the device actively cancels this connection through the
// management endpoint; a revoke, a shutdown and a client disconnect never
// close it.
type Subscription struct {
	info       Info
	cancel     chan struct{}
	cancelOnce sync.Once
}

// Info returns the subscription's immutable description.
func (s *Subscription) Info() Info { return s.info }

// Canceled returns the one-shot active-cancel signal.
func (s *Subscription) Canceled() <-chan struct{} { return s.cancel }

// Registry indexes every live push connection in the process. IDs are
// allocated here, so they are unique across both channels for the life of the
// process and are never reused after a connection leaves.
type Registry struct {
	mu   sync.Mutex
	next uint64
	live map[string]*Subscription
}

// NewRegistry returns an empty registry.
func NewRegistry() *Registry {
	return &Registry{live: make(map[string]*Subscription)}
}

// Register records one freshly established push connection and allocates its
// process-unique subscription ID. cursor is the handshake starting cursor for
// a change subscription and must be 0 for a state subscription. The returned
// subscription must be removed with Unregister when the connection ends.
func (r *Registry) Register(deviceID, documentID string, kind Kind, cursor int64) *Subscription {
	r.mu.Lock()
	r.next++
	seq := r.next
	id := formatID(seq)
	sub := &Subscription{
		info: Info{
			ID:            id,
			DeviceID:      deviceID,
			DocumentID:    documentID,
			Kind:          kind,
			Cursor:        cursor,
			EstablishedAt: time.Now().UnixMilli(),
			seq:           seq,
		},
		cancel: make(chan struct{}),
	}
	r.live[id] = sub
	r.mu.Unlock()
	return sub
}

// Unregister removes a connection that has ended. It is idempotent: a client
// disconnect, an active cancel and a shutdown may all race to call it.
func (r *Registry) Unregister(id string) {
	r.mu.Lock()
	delete(r.live, id)
	r.mu.Unlock()
}

// List returns the descriptions of every live connection belonging to
// deviceID, in connection-establishment order (oldest first). Subscriptions
// established by the device directly at the document level and those
// established through sessions it owns all appear, because both flows
// register under the resolved owning device.
func (r *Registry) List(deviceID string) []Info {
	r.mu.Lock()
	out := make([]Info, 0)
	for _, sub := range r.live {
		if sub.info.DeviceID == deviceID {
			out = append(out, sub.info)
		}
	}
	r.mu.Unlock()
	sort.Slice(out, func(i, j int) bool { return out[i].seq < out[j].seq })
	return out
}

// Cancel actively ends the live connection identified by id, but only when it
// currently belongs to deviceID: it removes the entry at once and closes its
// cancel signal, after which the connection layer finishes it with the active
// cancel close code. It returns false without signaling anything when the
// subscription does not exist, has already ended, or belongs to another
// device — those cases are indistinguishable to the caller, which answers
// 404 in every one of them.
func (r *Registry) Cancel(deviceID, id string) bool {
	r.mu.Lock()
	sub, ok := r.live[id]
	if !ok || sub.info.DeviceID != deviceID {
		r.mu.Unlock()
		return false
	}
	// Leave no window in which an already-canceled subscription can still be
	// listed: remove before signaling.
	delete(r.live, id)
	r.mu.Unlock()

	sub.cancelOnce.Do(func() { close(sub.cancel) })
	return true
}

// formatID renders the monotonic sequence as the subscription id. The prefix
// marks the token's origin in logs while the decimal stays unique within the
// process; ids are never reused.
func formatID(seq uint64) string {
	return "sub-" + strconv.FormatUint(seq, 10)
}

package server

import (
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
)

// handleDocumentSubscribe is the document-level WebSocket change subscription,
// the session view's counterpart that needs no session:
//
//	GET /v1/documents/{documentID}/changes/subscribe?deviceId=D&cursor=N
//
// The calling device is declared by the deviceId query parameter; no new
// authentication is introduced. Validation is fixed and entirely pre-upgrade,
// writing nothing:
//
//  1. cursor must be a non-negative decimal integer and the request must carry
//     a valid WebSocket upgrade handshake (400 JSON otherwise; a malformed path
//     is a 400 JSON too),
//  2. the declared device must currently be registered — a missing or empty
//     deviceId is treated as an unregistered caller (404 JSON),
//  3. it must currently hold permission for the document (403 JSON).
//
// Everything after the upgrade is byte-for-byte the session subscription:
// committed changes past the starting cursor are paged out in cursor order as
// one {"id","deviceId","payload","cursor"} text frame per row, then live
// commits continue seamlessly. The connection is push-only, ends with 4403 on a
// later sticky revoke and with 1001 on a termination signal, and leaves no
// durable trace.
func handleDocumentSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	// Handshake and parameter shape first: a bad cursor is a 400 even when the
	// device is also unknown, matching the fixed validation order.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	// Device existence. A missing or empty deviceId is indistinguishable from
	// an unregistered one: 404 JSON, before any document content is observed.
	deviceID := r.URL.Query().Get("deviceId")
	if deviceID == "" {
		writeError(w, http.StatusNotFound, "device not found")
		return
	}
	exists, err := s.DeviceExists(deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up device")
		return
	}
	if !exists {
		writeError(w, http.StatusNotFound, "device not found")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 could not be written and the connection has been hijacked
		// (or is gone); no JSON error can be produced and nothing was
		// registered.
		return
	}

	// The post-upgrade connection shares the session subscription's exact
	// pump: catch-up paging, live fan-out, push-only inbound frames, 4403
	// revoke and 1001 shutdown.
	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/push"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// subscribePageLimit is the page size used while replaying changes already
// committed after the subscription cursor. It matches the largest page the
// paginated read endpoint accepts, so catch-up and reads stay page-aligned.
const subscribePageLimit = 1000

// wsCloseEchoWait bounds how long a server-initiated close waits for the
// client's close echo before the deferred TCP teardown.
const wsCloseEchoWait = 500 * time.Millisecond

// handleSubscribe is the WebSocket document subscription mounted under the
// session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe?cursor=N
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential. Validation happens entirely before
// the 101 handshake and writes nothing:
//
//  1. cursor must be a non-negative decimal integer (400 JSON otherwise),
//  2. the request must carry a valid WebSocket upgrade handshake (400 JSON),
//  3. the session must currently exist (404 JSON),
//  4. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first sends every committed change with a
// cursor greater than the starting cursor — paged in cursor order, one text
// frame per record in the exact {"id","deviceId","payload","cursor"} shape of
// a paginated read row — then seamlessly continues with changes committed by
// any write path (batch post, merge, restore, replay). Frames are never
// reordered or coalesced; a later read from the last observed cursor returns
// the same rows. The connection is push-only: inbound data frames are read
// and discarded, only close/ping control frames are honored.
//
// A permission revoked after the upgrade ends the subscription with close
// code 4403 and no further frame follows; a termination signal ends every
// subscription with 1001. A client disconnect simply unregisters — like long
// polling, a subscription writes no change, cursor or other record.
func handleSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Parameter shape first: a bad cursor is a 400 even when the session or
	// handshake is also bad, matching the session-scoped read ordering.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 response could not be written and the connection has been
		// hijacked (or is gone), so no JSON error can be produced. Nothing
		// was registered or written to the store.
		return
	}

	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

// parseSubscribeCursor validates the mandatory cursor query parameter: it
// must be present and a decimal non-negative integer. Negative, fractional
// and non-numeric values are a 400 JSON error; signs and adornments are
// rejected.
func parseSubscribeCursor(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.URL.Query().Get("cursor")
	// parseCursorPath accepts only decimal digits (no sign, fraction or
	// exponent); a missing parameter is an empty raw and is rejected too.
	cursor, ok := parseCursorPath(raw)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return 0, false
	}
	return cursor, true
}

// serveSubscription runs one upgraded connection to completion. It registers
// before the first log read (a commit landing during catch-up is therefore
// never missed), then alternates a flush phase — drain every page of changes
// past the last sent cursor — and a park phase on the wake channel. A revoke
// is acted on only after the committed tail is flushed, so a commit that was
// authorized when it landed is still delivered ahead of the 4403. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveSubscription(r *http.Request, s *app.App, conn *wsConn, documentID, deviceID string, cursor int64) {
	// Registration precedes the first read: the wake channel is buffered, so
	// a commit during a read leaves a pending wake that makes the next park
	// return immediately — no wake is lost. The revoked channel closes once
	// if access is withdrawn, and that event survives a racing re-grant.
	wakeCh, revokedCh, unregister := s.AddSubscription(documentID, deviceID)
	// The management-plane record makes this connection listable and
	// cancelable by its owning device. It is pure memory: removal is the only
	// teardown and it neither writes nor advances anything.
	managed := s.RegisterPush(deviceID, documentID, push.KindChanges, cursor)
	defer func() {
		unregister()
		s.UnregisterPush(managed.Info().ID)
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				// A malformed frame ends the connection with the RFC
				// protocol-error code; a client close is already echoed
				// inside ReadMessage; a network drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(err, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and
			// discarded; the client cannot mutate the log over it.
		}
	}()

	// checkEnd non-blockingly maps a closing store to 1001, an active device
	// cancel to 4410 and a sticky revoke to 4403; it returns true when the
	// subscription must end. A termination signal takes precedence: SIGTERM
	// must end every subscription with 1001 even if a cancel or a revoke is
	// also pending.
	checkEnd := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-managed.Canceled():
			endSubscription(conn, clientGone, wsCloseSubscriptionCanceled, "subscription canceled")
			return true
		default:
		}
		select {
		case <-revokedCh:
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	position := cursor
	first := true
	for {
		if !first {
			// Park until a commit, a sticky revoke or the termination signal
			// wakes us. r.Context() covers a non-shutdown cancel; the read
			// pump covers a client disconnect.
			select {
			case <-wakeCh:
				// Drain any coalesced follow-up signal as well; the flush
				// below reconciles every case by re-reading from the last
				// sent cursor.
				select {
				case <-wakeCh:
				default:
				}
			case <-managed.Canceled():
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsCloseSubscriptionCanceled, "subscription canceled")
				return
			case <-revokedCh:
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
				return
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			}
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
		}
		first = false

		// Flush phase: page every change past position in cursor order. A
		// termination signal or a revoke is honored between pages/rows so a
		// large catch-up cannot delay the closing frame. A revoke arriving
		// while the final already-authorized tail is in flight is checked
		// after the inner loop, so that tail still goes out first.
		for {
			if checkEnd() {
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}

			changes, _, err := s.ListChanges(documentID, position, subscribePageLimit)
			if err != nil {
				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			for i := range changes {
				if checkEnd() {
					return
				}
				raw, marshalErr := json.Marshal(changes[i])
				if marshalErr != nil {
					_ = conn.Close(wsCloseInternalError, "internal error")
					return
				}
				if writeErr := conn.WriteText(raw); writeErr != nil {
					return
				}
				position = changes[i].Cursor
			}
			if len(changes) < subscribePageLimit {
				break
			}
		}

		// Caught up. A revoke that arrived during the last page (its tail was
		// just flushed) now ends the subscription; otherwise loop and park.
		// Closing still wins over a pending revoke.
		if checkEnd() {
			return
		}
	}
}

// endSubscription sends the mandated closing frame and briefly waits for the
// read pump to observe the peer's close echo, so a graceful close reaches the
// client instead of being truncated by the deferred TCP teardown. It returns
// promptly if the peer is already gone; the caller's deferred NetClose drops
// the socket either way.
func endSubscription(conn *wsConn, clientGone <-chan struct{}, code int, reason string) {
	_ = conn.Close(code, reason)
	timer := time.NewTimer(wsCloseEchoWait)
	defer timer.Stop()
	select {
	case <-clientGone:
	case <-timer.C:
	}
}

// Change-log compaction moves the old end of a document's change log out of
// the online tables without touching the cursor space the log shares with
// every write path.
//
// The compaction boundary is the greatest cursor that has a saved snapshot
// (zero when the document has none): everything at or below it is reproducible
// from a snapshot plus the surviving tail, so those rows leave the online log.
// A trimmed change is not forgotten, though — its id keeps a small canonical
// summary (the originating device, a digest of the payload and, for a restore,
// the snapshot it came from, plus the cursor it was first assigned) so the
// submission layer keeps answering idempotency and conflict exactly as before.
// The summary never participates in reads: pagination, long polling and
// subscriptions simply no longer see the trimmed rows, and the summary's
// fixed size means storage does not grow back to the pre-compaction shape.
//
// Compaction itself is not a change: it allocates no cursor, writes no change
// record and wakes no waiter or subscriber. The cursor space never resets —
// the next allocated cursor is one past the greater of the online maximum and
// the boundary — and the boundary, the summaries and the read results are
// durable across restarts.

package events

import (
	"bytes"
	"crypto/sha256"
	"database/sql"
	"encoding/json"
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// CompactChanges moves every change of documentID whose cursor is at or below
// the compaction boundary out of the online log, in one serialized
// transaction, and returns the boundary together with the number of changes
// removed by this call.
//
// The boundary is the greatest cursor with a saved snapshot, or zero when the
// document has no snapshot — compacting a snapshot-less or unknown document
// succeeds and removes nothing. The gate is enforced before any content is
// observed, exactly as in ReplayChanges: an unregistered device yields
// store.ErrDeviceNotFound and a revoked device yields store.ErrPermissionDenied,
// and neither touches any state.
//
// Each trimmed id keeps its canonical summary (device, payload digest, restore
// provenance and first cursor) so re-posting it stays idempotent and a
// differing re-post stays a conflict. Compaction is idempotent: a repeat finds
// the same boundary, trims nothing and reports zero removed. It commits no
// change row, allocates no cursor and notifies no waiter or subscriber.
func (s *Service) CompactChanges(documentID, deviceID string) (boundary, removed int64, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, 0, err
	}
	defer func() { _ = tx.Rollback() }()

	// Registration and permission are enforced before any change content is
	// observed, so a rejected compaction cannot reveal anything.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
			return 0, 0, err
		}
	}

	// The boundary is the greatest cursor with a saved snapshot, 0 when the
	// document has none (an unknown document included).
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM snapshots WHERE document_id = ?`,
		documentID,
	).Scan(&boundary); err != nil {
		return 0, 0, err
	}
	stored, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return 0, 0, err
	}
	if boundary <= stored {
		// Nothing new to trim (a repeat compaction, or a snapshot-less
		// document): report the standing boundary and remove nothing.
		return stored, 0, tx.Commit()
	}

	// Collect the rows leaving the online log before deleting them: each one
	// first moves its canonical summary into the identity table.
	type trimmed struct {
		cursor  int64
		id      string
		device  string
		payload []byte
	}
	rows, err := tx.Query(
		`SELECT cursor, id, device_id, payload FROM changes
		 WHERE document_id = ? AND cursor <= ?
		 ORDER BY cursor ASC`,
		documentID, boundary,
	)
	if err != nil {
		return 0, 0, err
	}
	var dropping []trimmed
	for rows.Next() {
		var t trimmed
		if err := rows.Scan(&t.cursor, &t.id, &t.device, &t.payload); err != nil {
			_ = rows.Close()
			return 0, 0, err
		}
		dropping = append(dropping, t)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return 0, 0, err
	}
	_ = rows.Close()

	for _, t := range dropping {
		// A restored change also carries its provenance into the summary, so a
		// repeated restore keeps its idempotency/conflict decision.
		var restoredFrom sql.NullInt64
		err := tx.QueryRow(
			`SELECT snapshot_cursor FROM restores WHERE document_id = ? AND change_id = ?`,
			documentID, t.id,
		).Scan(&restoredFrom)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			restoredFrom = sql.NullInt64{}
		case err != nil:
			return 0, 0, err
		}
		digest, err := payloadDigest(t.payload)
		if err != nil {
			return 0, 0, err
		}
		if _, err := tx.Exec(
			`INSERT OR IGNORE INTO change_identities
				(document_id, id, device_id, digest, cursor, restored_from)
			 VALUES (?, ?, ?, ?, ?, ?)`,
			documentID, t.id, t.device, digest, t.cursor, restoredFrom,
		); err != nil {
			return 0, 0, err
		}
	}

	if _, err := tx.Exec(
		`DELETE FROM restores WHERE document_id = ? AND change_cursor <= ?`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}
	if _, err := tx.Exec(
		`DELETE FROM changes WHERE document_id = ? AND cursor <= ?`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}
	if _, err := tx.Exec(
		`INSERT INTO change_boundaries (document_id, boundary) VALUES (?, ?)
		 ON CONFLICT (document_id) DO UPDATE SET boundary = excluded.boundary`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}

	if err := tx.Commit(); err != nil {
		return 0, 0, err
	}
	// Compaction is not a change: no waiter is woken and no subscriber is
	// signaled, because no new change exists to observe.
	return boundary, int64(len(dropping)), nil
}

// boundaryOfTx returns the stored compaction boundary of documentID, or zero
// when the document was never compacted.
func boundaryOfTx(q store.DBTX, documentID string) (int64, error) {
	var boundary int64
	err := q.QueryRow(
		`SELECT boundary FROM change_boundaries WHERE document_id = ?`,
		documentID,
	).Scan(&boundary)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return 0, nil
	case err != nil:
		return 0, err
	default:
		return boundary, nil
	}
}

// currentCursorTx returns the document's high-water mark: the greatest online
// cursor, or the compaction boundary when every change up to it has left the
// online log. The cursor space never resets, so a fully trimmed document
// continues from its boundary rather than from zero.
func currentCursorTx(tx *sql.Tx, documentID string) (int64, error) {
	var maxOnline int64
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&maxOnline); err != nil {
		return 0, err
	}
	boundary, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return 0, err
	}
	if boundary > maxOnline {
		maxOnline = boundary
	}
	return maxOnline, nil
}

// payloadDigest renders a payload in the canonical form JSONEqual compares —
// the decoded value re-encoded, so 1 and 1.0 or reordered object keys digest
// alike — and hashes it. The digest is the fixed-size stand-in for the payload
// in a trimmed change's retained summary.
func payloadDigest(payload json.RawMessage) ([]byte, error) {
	var v any
	if err := json.Unmarshal(payload, &v); err != nil {
		return nil, err
	}
	canonical, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	sum := sha256.Sum256(canonical)
	return sum[:], nil
}

// resolveTrimmedIdentity answers the submission question for an id whose
// online row is absent because compaction trimmed it. It returns found=true
// and the id's first cursor when the retained summary matches the incoming
// device and payload (an idempotent re-post), an *ErrConflict when a retained
// summary exists but differs, and found=false when no summary was retained (a
// genuinely new id).
func resolveTrimmedIdentity(tx *sql.Tx, documentID string, c Change) (found bool, cursor int64, err error) {
	var device string
	var digest []byte
	err = tx.QueryRow(
		`SELECT device_id, digest, cursor FROM change_identities WHERE document_id = ? AND id = ?`,
		documentID, c.ID,
	).Scan(&device, &digest, &cursor)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, 0, nil
	case err != nil:
		return false, 0, err
	}

	incoming, err := payloadDigest(c.Payload)
	if err != nil {
		return false, 0, err
	}
	if device != c.DeviceID || !bytes.Equal(digest, incoming) {
		return false, 0, &ErrConflict{ID: c.ID}
	}
	return true, cursor, nil
}

