package crdt

import (
	"errors"
	"sync"
)

// subKey identifies the set of CRDT state subscriptions belonging to one
// device's view of one document: a state-changing commit fans out to every
// device set under the document, a permission revoke closes only the one
// (document, device) set.
type crdtSubKey struct {
	document string
	device   string
}

// Subscription is one in-memory, push-only subscription to a document's
// merged CRDT state. States that actually changed the merge are appended in
// transaction-commit order and handed to the connection in that order; the
// wake channel is merely a coalescing "drain the queue" signal. A permission
// revoke targeting the subscription's (document, device) pair is delivered as
// a separate, one-shot closed channel so it can neither be missed nor undone
// by a later grant on the same connection.
//
// A subscription leaves no durable trace: nothing is written, a disconnect
// simply unregisters, and stopping wakes every subscription once. Pushing
// never writes an operation and never moves the merge.
type Subscription struct {
	// mu guards queue.
	mu sync.Mutex
	// queue holds merged states in commit order the connection has not
	// drained yet. It is unbounded: every committed state change must reach
	// the subscriber exactly once and in order.
	queue []State
	// wakes is a 1-buffered "drain now" signal.
	wakes chan struct{}
	// revoked is closed once, the first time permission for the keyed pair is
	// revoked while this subscription is live. Closing is sticky.
	revoked       chan struct{}
	revokedClosed bool
}

// Wake returns the coalescing drain signal.
func (x *Subscription) Wake() <-chan struct{} { return x.wakes }

// Revoked returns the one-shot revoke signal.
func (x *Subscription) Revoked() <-chan struct{} { return x.revoked }

// Drain removes and returns every queued merged state in commit order. It
// returns nil when the queue is empty.
func (x *Subscription) Drain() []State {
	x.mu.Lock()
	defer x.mu.Unlock()
	if len(x.queue) == 0 {
		return nil
	}
	out := x.queue
	x.queue = nil
	return out
}

// deliver appends a committed merged state and pokes the drain signal. It is
// non-blocking: a wake already pending covers this state because the consumer
// drains the whole queue each time it runs.
func (x *Subscription) deliver(state State) {
	x.mu.Lock()
	x.queue = append(x.queue, state)
	x.mu.Unlock()
	select {
	case x.wakes <- struct{}{}:
	default:
	}
}

// AddSubscription registers an in-memory subscription to documentID as seen by
// deviceID and returns it together with an idempotent unregister that a
// client disconnect, a permission close and a service stop may all race to
// call.
//
// Registration precedes the subscriber's first state read, so a
// state-changing commit landing between registration and that read is queued
// and cannot be missed. If the service is already stopping the wake is
// signaled immediately and unregister is a no-op.
func (s *Service) AddSubscription(documentID, deviceID string) (*Subscription, func()) {
	sub := &Subscription{
		wakes:   make(chan struct{}, 1),
		revoked: make(chan struct{}),
	}
	key := crdtSubKey{document: documentID, device: deviceID}

	s.subMu.Lock()
	defer s.subMu.Unlock()
	if s.closed {
		close(sub.wakes)
		return sub, func() {}
	}
	s.subWG.Add(1)
	s.nextSubID++
	id := s.nextSubID
	set := s.subs[key]
	if set == nil {
		set = make(map[uint64]*Subscription)
		s.subs[key] = set
	}
	set[id] = sub
	unregister := func() {
		s.subMu.Lock()
		if set, ok := s.subs[key]; ok {
			if _, ok := set[id]; ok {
				delete(set, id)
				if len(set) == 0 {
					delete(s.subs, key)
				}
				s.subMu.Unlock()
				s.subWG.Done()
				return
			}
		}
		s.subMu.Unlock()
	}
	return sub, unregister
}

// OpenSubscription atomically registers a state subscription and reads the
// document's current merged state. It returns:
//
//   - state: the current merged state, or nil when no CRDT operation has ever
//     been committed (the subscriber then waits silently);
//   - sub: the live subscription;
//   - unregister: idempotent removal.
//
// Registration and the read happen as one step relative to a SubmitOps commit
// — both hold the serialization mutex — so a state-changing commit lands
// either inside the returned initial state or in the subscription's queue,
// never both and never neither.
func (s *Service) OpenSubscription(documentID, deviceID string) (state *State, sub *Subscription, unregister func(), err error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	sub, unregister = s.AddSubscription(documentID, deviceID)
	current, getErr := s.GetState(documentID)
	switch {
	case errors.Is(getErr, ErrNotFound):
		return nil, sub, unregister, nil
	case getErr != nil:
		unregister()
		return nil, nil, func() {}, getErr
	}
	return &current, sub, unregister, nil
}

// notifySubscribers publishes a newly merged state to every subscription open
// on documentID. It is called only after a state-changing transaction has
// committed, so every pushed state is durable and states arrive in
// transaction-commit order.
func (s *Service) notifySubscribers(documentID string, state State) {
	s.subMu.Lock()
	var targets []*Subscription
	for key, set := range s.subs {
		if key.document != documentID {
			continue
		}
		for _, sub := range set {
			targets = append(targets, sub)
		}
	}
	s.subMu.Unlock()

	for _, sub := range targets {
		sub.deliver(state)
	}
}

// PermissionRevoked closes the one-shot revoked channel of every CRDT
// subscription open on (documentID, deviceID), so the connection layer ends
// those subscriptions with the permission-closed code even if a grant races
// in afterward. It satisfies authz.RevokeSink; other devices' and documents'
// subscriptions are untouched.
func (s *Service) PermissionRevoked(documentID, deviceID string) {
	s.subMu.Lock()
	set := s.subs[crdtSubKey{document: documentID, device: deviceID}]
	targets := make([]*Subscription, 0, len(set))
	for _, sub := range set {
		if !sub.revokedClosed {
			sub.revokedClosed = true
			targets = append(targets, sub)
		}
	}
	s.subMu.Unlock()

	for _, sub := range targets {
		close(sub.revoked)
	}
}

// SignalDeviceDeregistered ends every live CRDT subscription belonging to
// deviceID across every document, after the device's deregistration
// transaction committed: the session that backed such a connection is already
// hard-deleted, so it closes immediately with the same permission-closed code
// a revoke uses, stickily. Other devices' subscriptions are untouched.
func (s *Service) SignalDeviceDeregistered(deviceID string) {
	s.subMu.Lock()
	var targets []*Subscription
	for key, set := range s.subs {
		if key.device != deviceID {
			continue
		}
		for _, sub := range set {
			if !sub.revokedClosed {
				sub.revokedClosed = true
				targets = append(targets, sub)
			}
		}
	}
	s.subMu.Unlock()

	for _, sub := range targets {
		close(sub.revoked)
	}
}

// Closing reports whether the service has begun stopping. A woken subscription
// uses it to distinguish a termination signal from a state change.
func (s *Service) Closing() bool {
	s.subMu.Lock()
	defer s.subMu.Unlock()
	return s.closed
}

// InterruptWaits gives every live subscription one coalescing wake during
// shutdown and marks the service as stopping; the connection layer re-checks
// the flag and finishes each connection with a going-away close. Committed
// state is untouched.
func (s *Service) InterruptWaits() {
	s.subMu.Lock()
	s.closed = true
	var targets []*Subscription
	for _, set := range s.subs {
		for _, sub := range set {
			targets = append(targets, sub)
		}
	}
	s.subMu.Unlock()

	for _, sub := range targets {
		select {
		case sub.wakes <- struct{}{}:
		default:
		}
	}
}

// WaitDrained blocks until every subscription handler has unregistered.
func (s *Service) WaitDrained() {
	s.subWG.Wait()
}

package server

import (
	"bytes"
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/push"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// handleCRDTStateSubscribe is the WebSocket subscription to a document's
// merged CRDT state, mounted under the session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state/subscribe
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential and no new auth is introduced. The
// validation order is fixed and entirely pre-upgrade, writing nothing:
//
//  1. the request must be a GET carrying a valid WebSocket upgrade handshake
//     (400 JSON otherwise; a malformed path is a 400 JSON too),
//  2. the session must currently exist (404 JSON),
//  3. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first pushes the current merged state; a
// document without any CRDT operation yet sends nothing and waits silently
// until its first state appears. From then on every commit that actually
// changes the merge — a counter's per-device maximum advancing, the set union
// growing, the register's winning value changing — is pushed as one text
// frame in transaction-commit order.
// Idempotent repeats, rejected regressions and wholly invalid batches change
// no state and produce no frame; re-adding an existing set element pushes
// nothing either.
//
// Each message is one text frame whose payload is byte-for-byte the state
// read endpoint's body: compact single-line JSON with the keys in type, value
// order, terminated by a newline. The connection is push-only: inbound data
// frames are read and discarded, ping is answered with pong. A permission
// revoke after the upgrade ends the subscription with close code 4403 —
// stickily, a re-grant never revives this connection — and a termination
// signal ends every subscription with 1001. Subscriptions are not persisted;
// after a restart a fresh subscription immediately receives the consistent
// current merged state.
func handleCRDTStateSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 could not be written and the connection has been hijacked
		// (or is gone); no JSON error can be produced and nothing was
		// registered.
		return
	}

	serveCRDTStateSubscription(r, s, conn, documentID, deviceID)
}

// serveCRDTStateSubscription runs one upgraded CRDT-state connection to
// completion. Registration and the initial state read are one atomic step in
// the store, so a state-changing commit lands either inside that initial
// state or in the subscription's queue: the first frame is the current merge
// and every later frame is strictly newer, in commit order. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveCRDTStateSubscription(r *http.Request, s *app.App, conn *wsConn, documentID, deviceID string) {
	initial, sub, unregister, err := s.OpenCRDTSubscription(documentID, deviceID)
	if err != nil {
		_ = conn.Close(wsCloseInternalError, "internal error")
		_ = conn.NetClose()
		return
	}
	// The management-plane record makes this connection listable and
	// cancelable by its owning device. A state subscription carries no
	// starting cursor, so the recorded cursor is 0.
	managed := s.RegisterPush(deviceID, documentID, push.KindState, 0)
	defer func() {
		unregister()
		s.UnregisterPush(managed.Info().ID)
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, readErr := conn.ReadMessage(); readErr != nil {
				// A malformed frame ends with the RFC protocol-error code; a
				// client close is already echoed inside ReadMessage; a network
				// drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(readErr, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and discarded;
			// the client cannot submit or mutate any operation over it.
		}
	}()

	// endNow maps a closing store to 1001, an active device cancel to 4410
	// and a sticky revoke to 4403, waiting briefly for the peer's close echo.
	// Termination takes precedence over a racing cancel or revoke. It returns
	// true when the subscription must end.
	endNow := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-managed.Canceled():
			endSubscription(conn, clientGone, wsCloseSubscriptionCanceled, "subscription canceled")
			return true
		default:
		}
		select {
		case <-sub.Revoked():
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	// closingOnly honors a termination signal before the first frame; a revoke
	// racing the initial push is left for the main loop so the state that was
	// authorized at handshake still reaches the client ahead of the 4403.
	closingOnly := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		return false
	}

	// lastSent skips any queued frame that encodes the same state the
	// connection already sent. Registration-vs-commit atomicity already makes
	// this unnecessary (a queued state is always strictly newer), so this is
	// only a belt-and-braces guard for the register/read boundary.
	var lastSent []byte
	send := func(state crdt.State) bool {
		frame := encodeCRDTStateFrame(state)
		if bytes.Equal(frame, lastSent) {
			return true
		}
		if writeErr := conn.WriteText(frame); writeErr != nil {
			return false
		}
		lastSent = frame
		return true
	}

	// First push: the current merged state. A document with no operation yet
	// stays silent until its first state arrives. A termination signal that
	// raced the registration is honored before anything is sent.
	if closingOnly() {
		return
	}
	if initial != nil {
		if !send(*initial) {
			return
		}
	}

	for {
		if endNow() {
			return
		}

		// Drain every committed state queued since the last park, in commit
		// order; a revoke or termination is honored between frames.
		for _, state := range sub.Drain() {
			if endNow() {
				return
			}
			if !send(state) {
				return
			}
		}
		if endNow() {
			return
		}

		select {
		case <-sub.Wake():
			// A coalescing "drain now" signal; loop and flush the whole queue.
		case <-managed.Canceled():
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
			endSubscription(conn, clientGone, wsCloseSubscriptionCanceled, "subscription canceled")
			return
		case <-sub.Revoked():
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return
		case <-clientGone:
			return
		case <-r.Context().Done():
			return
		}
	}
}

// encodeCRDTStateFrame renders one state message exactly as the state read
// endpoints render their bodies: the shared encoder (HTML escaping included,
// map keys sorted to type then value) and the same trailing newline, so a
// pushed frame can be compared byte-for-byte with a GET .../crdt/state
// response at either the document or session path.
func encodeCRDTStateFrame(state crdt.State) []byte {
	return marshalCRDTState(state)
}

package events

import (
	"context"
	"database/sql"
	"time"
)

// DocumentExists reports whether documentID is a known document rather than an
// empty namespace: it has any online change row, or a compaction boundary from
// a log that was (fully or partially) trimmed.
func (s *Service) DocumentExists(documentID string) (bool, error) {
	var known bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)`,
		documentID, documentID,
	).Scan(&known); err != nil {
		return false, err
	}
	return known, nil
}

// ListChanges returns at most limit changes for documentID whose cursor is
// greater than after and still online, in cursor order, together with the
// cursor to pass as the next after value. An unknown document yields an empty
// list and cursor 0; a known document with no rows past after yields
// nextCursor == max(after, boundary), so a caller positioned inside the
// trimmed range resumes from the compaction boundary.
func (s *Service) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
	rows, err := s.db.Query(
		`SELECT id, device_id, payload, cursor FROM changes
		 WHERE document_id = ? AND cursor > ?
		 ORDER BY cursor ASC
		 LIMIT ?`,
		documentID, after, limit,
	)
	if err != nil {
		return nil, 0, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	var maxCursor int64 = after
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
		maxCursor = c.Cursor
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}

	// Distinguish an unknown document from a known one with nothing new:
	// unknown documents must report nextCursor 0, while a known document
	// reports the greater of after and the compaction boundary.
	if len(out) == 0 {
		known, err := s.DocumentExists(documentID)
		if err != nil {
			return nil, 0, err
		}
		if !known {
			return out, 0, nil
		}
		boundary, err := boundaryOfTx(s.db, documentID)
		if err != nil {
			return nil, 0, err
		}
		if boundary > maxCursor {
			maxCursor = boundary
		}
	}
	return out, maxCursor, nil
}

// ExportChanges returns every change of documentID whose cursor lies in the
// closed interval [from, to] and is still in the online log, in ascending
// cursor order. When to is nil no upper bound is applied. An unknown document,
// or a range without any online change — including one that lies entirely
// inside the trimmed region — yields an empty list and no error: the export is
// a read that misses like any other. The (document_id, cursor) unique index
// guarantees a cursor appears at most once.
//
// The single SELECT runs as one SQLite statement over the serialized
// connection, so a batch committed concurrently is observed either with all of
// its rows or not at all — never half of it. The read starts no transaction,
// writes nothing and notifies no waiters, so it cannot move a cursor, produce
// a change record or wake a parked poll. Each returned row is the same record
// the paged read emits at that cursor.
func (s *Service) ExportChanges(documentID string, from int64, to *int64) ([]ListedChange, error) {
	var (
		rows *sql.Rows
		err  error
	)
	if to == nil {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ?
			 ORDER BY cursor ASC`,
			documentID, from,
		)
	} else {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ? AND cursor <= ?
			 ORDER BY cursor ASC`,
			documentID, from, *to,
		)
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// WaitForChanges blocks until documentID has a change with cursor greater than
// after, a change is committed while waiting, wait elapses, ctx is canceled
// (the client disconnected) or the service stops. It then returns the current
// page of up to limit changes exactly as ListChanges would, with timedOut=true
// only when the wait deadline expired with no new rows.
//
// Registration precedes the first query: a commit landing between the read and
// the park still notifies a registered channel, so no change is missed.
//
// An unknown document is never parked on: it returns immediately with an empty
// list and nextCursor 0, timedOut=false. Data already past after is likewise
// returned immediately. wait <= 0 is an immediately expired deadline.
func (s *Service) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) (changes []ListedChange, nextCursor int64, timedOut bool, err error) {
	ch, remove := s.registerWait(documentID)
	defer remove()

	changes, nextCursor, err = s.ListChanges(documentID, after, limit)
	if err != nil || len(changes) > 0 {
		return changes, nextCursor, false, err
	}

	// Empty page: distinguish an unknown document (immediate empty/0, never
	// parked on) from a known document caught up to after.
	known, err := s.DocumentExists(documentID)
	if err != nil || !known {
		return changes, 0, false, err
	}

	// Known document, nothing new: a zero wait is an immediately expired
	// deadline; ListChanges already echoes nextCursor == after.
	if wait <= 0 {
		return changes, nextCursor, true, nil
	}

	timer := time.NewTimer(wait)
	defer timer.Stop()

	select {
	case <-ch:
		// Woken by a committed change or by InterruptWaits.
		s.mu.Lock()
		closing := s.closed
		s.mu.Unlock()
		if closing {
			return nil, 0, false, ErrStoreClosing
		}
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-timer.C:
		// Timeout with no new rows: echo the caller's cursor without
		// advancing it. The document was known above, so ListChanges returns
		// nextCursor == after for an empty page.
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-ctx.Done():
		return nil, 0, false, ctx.Err()
	}
}

// registerWait parks a channel for documentID and returns it together with a
// removal function. The channel is closed on the next committed change to the
// document, or when the service stops.
func (s *Service) registerWait(documentID string) (ch chan struct{}, remove func()) {
	ch = make(chan struct{}, 1)

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		// Shutdown beat the registration: signal immediately so the caller does
		// not park on a channel nobody will close.
		close(ch)
		return ch, func() {}
	}
	s.nextWait++
	id := s.nextWait
	set := s.waits[documentID]
	if set == nil {
		set = make(map[uint64]chan struct{})
		s.waits[documentID] = set
	}
	set[id] = ch
	return ch, func() {
		s.mu.Lock()
		if set, ok := s.waits[documentID]; ok {
			delete(set, id)
			if len(set) == 0 {
				delete(s.waits, documentID)
			}
		}
		s.mu.Unlock()
	}
}

// notifyWaiters signals every long poll parked on documentID and every
// subscription open on it. It is called only after a change-bearing
// transaction has committed, so parked readers observe the new rows when they
// re-query and pushed frames describe committed changes.
func (s *Service) notifyWaiters(documentID string) {
	s.mu.Lock()
	set := s.waits[documentID]
	delete(s.waits, documentID)
	s.mu.Unlock()
	for _, ch := range set {
		close(ch)
	}
	s.signalSubscribers(documentID)
}

