// every owning device — subscribed to documentID. It removes the entries at
// once and closes each document-deleted signal, after which the connection
// layer finishes them with the document-deleted close code. Subscriptions to
// other documents are untouched. It is called after the document's deletion
// transaction has committed.
func (r *Registry) CloseDocument(documentID string) {
	r.mu.Lock()
	var targets []*Subscription
	for id, sub := range r.live {
		if sub.info.DocumentID != documentID {
			continue
		}
		delete(r.live, id)
		targets = append(targets, sub)
	}
	r.mu.Unlock()

	for _, sub := range targets {
		sub.deleteOnce.Do(func() { close(sub.documentDeleted) })
	}
}

