// Subscription is one live registry entry. Its one-shot Canceled channel is
// closed exactly when the device actively cancels this connection through the
// management endpoint; a revoke, a shutdown and a client disconnect never
// close it. The DocumentDeleted channel is closed once when the document the
// connection subscribes to is deleted as a whole; that close spans both push
// channels and every device subscribed to the document.
type Subscription struct {
	info            Info
	cancel          chan struct{}
	cancelOnce      sync.Once
	documentDeleted chan struct{}
	deleteOnce      sync.Once
}

// Info returns the subscription's immutable description.
func (s *Subscription) Info() Info { return s.info }

// Canceled returns the one-shot active-cancel signal.
